-- 常量定义
local nPlayerMP = 1000				-- 玩家MP基数
local nRateMulti = 100				--几率类数据计算倍数
local nNormalAniSpeed = 2000				--正常普通攻击动画速度,单位:毫秒
local nNormalAtkSpeed = 1000				--正常普通攻击数值速度,单位:毫秒
local nPrimaryEquipFactor = 0.75				--初始装备属性系数
local nDropRateUpLimit = 10000000				--掉率随机数上限
local nEnchanceImprove = 0.18				--单次强化属性提升幅度
local nEnchanceTimes = #tEnchanceCostFactor			-- 最大强化次数

-- 获取一个数值的整数位数和小数余数
function GetNumLength( pNumber )
	local vLength, vDecimals = 0, 0

	local vNumber = pNumber
	local vInt = math.floor( pNumber )
	vDecimals = pNumber - vInt
	while vNumber > 1 do
		vLength = vLength + 1
		vNumber = vNumber / 10
	end

	return vLength, vDecimals
end

-- 计算物理防御点数转换为减伤百分比
-- 传入参数：
-- 		pTarDef = 防御点数
-- 		pAtkLv = 等级
-- 返回值：百分比（0~1之间小数）
function CalPhysicalDefense(pTarDef, pAtkLv)
	local vLvFactor, vFixFator, vTotalFactor = 15, 45, 0.75
	local vDP = pTarDef
	local vDmgReduceScale = 0

	if vDP < 0 then
	-- 避免防御点数因为各种计算出现负值之后的不可预料结果
		vDP = 0
	end
	vDmgReduceScale = vDP / ( vDP + vLvFactor * pAtkLv + vFixFator ) * vTotalFactor

	return vDmgReduceScale
end

-- 系统接口 -------------------------------------------------
-- 计算物理伤害，不考虑命中和暴击计算
-- param[in] pLv: 等级
-- param[in] pPhyAtk: 攻击力
-- param[in] pPhyDef: 防御点数
function CalPhysicalDamage(pLv, pPhyAtk, pPhyDef)
    local vPhyDmgReduce = CalPhysicalDefense(pPhyDef, pLv)
	local vPhyDmg = pPhyAtk * ( 1 - vPhyDmgReduce )
	-- print("		减伤比例：" .. math.floor( vPhyDmgReduce * 10000 ) / 100 .. "%	物理伤害：" .. vPhyDmg)
	return vPhyDmg
end

-- 系统接口 -------------------------------------------------
-- 计算元素伤害
function CalEleDmg(pEleAtk, pAtkLv, pEleRes, pTarLv)
	local vEleDmg = 0
	if pEleAtk > 0 then
		vEleDmg = pEleAtk * ( 1 - pEleRes / nRateMulti)
	else
		vEleDmg = nil
	end

	return vEleDmg
end

-- 系统接口 -------------------------------------------------
-- 计算暴击伤害
-- param[in] forceCri: 是否强制暴击
-- param[in] dam: 原伤害值
-- param[in] atkCri: 暴击率
-- param[in] atkCriDam: 暴击伤害
-- return: [1] - 结果伤害，[2] - 是否暴击
function CalCriticalDamage(forceCri, dam, atkCri, atkCriDam)
    local bCri = false
    if forceCri or sw.randi(1, nRateMulti) <= atkCri then
        bCri = true
        -- 计算暴击加成
        dam = dam * ( 1 + atkCriDam / nRateMulti )
    end
    return dam, bCri
end

-- 系统接口 -------------------------------------------------
-- 计算普通攻击伤害
-- param[in] tAttacker: 攻击者; param[in] tTarget: 被攻击的目标。属性（均为最终值）：
-- 				type - 单位类型字符串。怪物为"Monster"，主角为"MyPlayer"
-- 				lv - 等级
-- 				cur_hp - 当前hp
-- 				max_hp - 最大hp
-- 				cur_mp - 当前mp
-- 				max_mp - 最大mp
-- 				min_atk - 最小攻击
-- 				max_atk - 最大攻击
-- 				defense - 防御
-- 				fire_atk - 火攻
-- 				cold_atk - 冰攻
-- 				light_atk - 雷攻
-- 				poison_atk - 毒攻
-- 				fire_res - 火抗
-- 				cold_res - 冰抗
-- 				light_res - 雷抗
-- 				poison_res - 毒抗
-- 				hit - 命中
-- 				dodge - 闪避
-- 				critical - 暴击
-- 				crit_dam - 暴击伤害
-- 				raw_atk_speed - 原始攻击速度
-- 				fin_atk_speed - 最终攻击速度
-- param[in] forceHit: 强制命中
-- param[in] forceCrit: 强制暴击
-- return: 伤害值。如果miss，则返回nil
function CalAttackDamage(tAttacker, tTarget, forceHit, forceCrit)
	local vPhyDmg, vFireDmg, vColdDmg, vLightDmg, vPoisonDmg = 0, 0, 0, 0, 0
	local bHit, bBreak, bCri = false, false, false
	-- 攻击命中判定
	-- print("———— 本次攻击开始 ————" .. "	攻击方：" .. tAttacker.type .. "	等级：" .. tAttacker.lv .. "	目标方：" .. tTarget.type .. "	等级：" .. tTarget.lv)
	local vHit = tAttacker.hit
		-- 玩家命中率在面对高等级怪物时有扣减，每相差 5 级，降低 1%，最低到10%
        -- fix: 调整公式
	if tAttacker.type == "MyPlayer" then
        local dis = math.floor((tTarget.lv - tAttacker.lv) / 5);
        if (dis > 0) then
            vHit = math.max(10, vHit - dis);
        end
	end
	-- print("	物理攻击计算 ——")
	-- print("		攻击方命中：" .. tAttacker.hit .. "%	扣减后命中：" .. vHit .. "%")
	local vHitRate = vHit - tTarget.dodge
	local vrate = sw.randi(1, nRateMulti)
	if forceHit or vrate <= vHitRate then
		bHit = true
	-- 	print("		目标方闪避：" .. tTarget.dodge .. "%	命中差值：" .. vHitRate .. "%	成功命中目标")
	-- else
	-- 	print("		目标方闪避：" .. tTarget.dodge .. "%	命中差值：" .. vHitRate .. "%	未能命中")
	end
	-- 命中后伤害计算
	if bHit then
		-- 物理伤害计算
		local vPhyAtk = sw.randi(tAttacker.min_atk, tAttacker.max_atk)
		if vPhyAtk > 0 then
--			print("		攻击力：" .. tAttacker.min_atk .." ~ " .. tAttacker.max_atk .. "	实际取值：" .. vPhyAtk .. "	防御力：" .. tTarget.defense)
			vPhyDmg = CalPhysicalDamage(tAttacker.lv, vPhyAtk, tTarget.defense)
			-- 判断暴击
			vPhyDmg, bCri = CalCriticalDamage(forceCrit, vPhyDmg, tAttacker.critical, tAttacker.crit_dam)
			-- local sPhyAtkMsg = "		本次物理攻击"
			-- if bCri then
				-- sPhyAtkMsg = sPhyAtkMsg .. "产生 ※ 暴击 ※，"
			-- else
				-- sPhyAtkMsg = sPhyAtkMsg .. "未出现暴击，"
			-- end
			-- sPhyAtkMsg = sPhyAtkMsg .. "最终伤害：" .. vPhyDmg
			-- print(sPhyAtkMsg)
		end
		-- 元素伤害计算
		vFireDmg = CalEleDmg(tAttacker.fire_atk, tAttacker.lv, tTarget.fire_res, tTarget.lv)
		vColdDmg = CalEleDmg(tAttacker.cold_atk, tAttacker.lv, tTarget.cold_res, tTarget.lv)
		vLightDmg = CalEleDmg(tAttacker.light_atk, tAttacker.lv, tTarget.light_res, tTarget.lv)
		vPoisonDmg = CalEleDmg(tAttacker.poison_atk, tAttacker.lv, tTarget.poison_res, tTarget.lv)
		-- print("	附加元素伤害计算 ——")
		-- print("		火焰：攻击：" .. tAttacker.fire_atk .. "	抗性：" .. tTarget.fire_res .. "%	造成伤害：" .. vFireDmg )
		-- print("		冰霜：攻击：" .. tAttacker.cold_atk .. "	抗性：" .. tTarget.cold_res .. "%	造成伤害：" .. vColdDmg )
		-- print("		闪电：攻击：" .. tAttacker.light_atk .. "	抗性：" .. tTarget.light_res .. "%	造成伤害：" .. vLightDmg )
		-- print("		毒素：攻击：" .. tAttacker.poison_atk .. "	抗性：" .. tTarget.poison_res .. "%	造成伤害：" .. vPoisonDmg )
		-- print("———— 本次攻击结束 ————	总伤害：" .. vPhyDmg + vFireDmg + vColdDmg + vLightDmg + vPoisonDmg)
	else		-- 未命中，返回nil
		vPhyDmg = nil
		vFireDmg = nil
		vColdDmg = nil
		vLightDmg = nil
		vPoisonDmg = nil
		-- print("———— 本次攻击结束 ————	攻击Miss")
	end

	return vPhyDmg, vFireDmg, vColdDmg, vLightDmg, vPoisonDmg, bCri
end

-- 获取装备等级对应的GS系数
-- 传入参数：
--		pLevel = 等级
function GetGSBase(pLevel)
	local nBase = 8		-- GS基数
	local nLinearFactor = 2		-- GS线性系数
	local nExponentialFactor = 1.0305	-- GS指数系数
	local vGS1, vGS2 = 0, 0
	local vGSLv = pLevel + math.max( 0, math.floor( ( pLevel - 21 ) / 10 + 1 ) * 5 )
	vGS1 = nBase + nLinearFactor * ( vGSLv - 1 )		-- 线性增长值
	vGS2 = nBase * nExponentialFactor ^ ( vGSLv - 1 )		-- 指数增长值
	-- local vBaseGS = math.floor( math.min( 20000, math.max( vGS1, vGS2 ) * 1000 ) / 1000	)	-- 计算结果保留 3 位小数
	local vBaseGS = vGS1

	return vBaseGS
end

-- 获取法力上限计算基础值
-- 传入参数：
-- 		pLevel = 等级
-- 		pQuality = 品质
-- 		pNumType = 数值类型，1 = 点数；0 = 百分比
function GetMPBase(pLevel, pQuality, pNumType)
	if pNumType == 1 then
		return 800, 1200
	else
		return 0.8, 1.2
	end
end

-- 获取装备类型
-- 传入参数：
--		pEquipType = 原始装备类型
--		pMode = WEAPON：转换所有武器为统一类型；NONE：不转换
function GetEquipType(pEquipType, pMode)
	local vType = pEquipType
	-- 如果指定转换武器类型则进行转换
	if pMode == "WEAPON" then
		if pEquipType == tItemType.mLight or pEquipType == tItemType.mHeavy or pEquipType == tItemType.mPolearms then
			vType = tItemType.mWeapon
		end
	end

	return vType
end

-- 获取装备基础属性数值
-- 传入参数：
-- 		pID = 装备的物品ID
-- 		pType = 原始装备类型
-- 		pQuality = 装备品质
-- 		pAttrLv = 装备属性等级
-- 		pAtkSpd = 攻击速度（只对武器有效）
-- 		pAttrID = 扩展属性ID
-- 返回值：
-- 		vAttrValueLow = 属性数值下限
-- 		vAttrValueUp = 属性数值上限
function GetEquipBaseAttrValue(pID, pType, pQuality, pAttrLv, pAtkSpd, pAttrID)
	local vAttrValueLow, vAttrValueUp = 0, 0
	local vEquipType = GetEquipType(pType, "WEAPON")
	if tExtendAttrFactor[pAttrID][2] == 0 then
		-- 百分比数值计算
		-- print("		属性ID：" .. pAttrID .. "		内容：" .. tExtendAttrFactor[pAttrID][19])
		if pAttrID == 8 then
			-- MP的计算流程
			vAttrValueLow, vAttrValueUp = GetMPBase(pAttrLv, pQuality, 0)
			vAttrValueLow = vAttrValueLow * nRateMulti
			vAttrValueUp = vAttrValueUp * nRateMulti
		else
			-- 其他属性
			local vBase = tExtendAttrFactor[pAttrID][pQuality + 6][1]
			local vLvUp = tExtendAttrFactor[pAttrID][pQuality + 6][2]
			local vLvGrade = math.floor( ( pAttrLv - 1 ) / tExtendAttrFactor[pAttrID][4] )
			local vFloat = tExtendAttrFactor[pAttrID][pQuality + 6][3]
				-- 基础值 = 品质对应基数 + 等级成长 × 等级段 - 浮动值
			vAttrValueLow = ( vBase + vLvUp * vLvGrade - vFloat ) * nRateMulti
			vAttrValueUp = ( vBase + vLvUp * vLvGrade + vFloat ) * nRateMulti
			-- print("			基础值：" .. vBase .. "等级浮动：" .. vLvUp .. "等级段：" .. vLvGrade .. "上浮范围：" .. vFloat)
		end
	else
		-- 点数类数值计算
		-- print("	属性ID：" .. pAttrID .. "		内容：" .. tExtendAttrFactor[pAttrID][19])
		if pAttrID == 7 then
			-- MP的计算流程
			vAttrValueLow, vAttrValueUp = GetMPBase(pAttrLv, pQuality, 1)
			-- fix: 根据装备等级浮动
			vAttrValueLow = math.floor(vAttrValueLow * pAttrLv / 100)
			vAttrValueUp = math.floor(vAttrValueUp * pAttrLv / 100)
		else
			-- 其他属性
				-- 基础值 =     基础GS ×             属性对应GS系数 ×                  品质系数 ×                      部件分配比例
			local vBaseValue = GetGSBase(pAttrLv) * tExtendAttrFactor[pAttrID][5] * tQualityFactor[pQuality][1] * tPartScale[pAttrID][vEquipType]
			-- print(GetGSBase(pAttrLv), tExtendAttrFactor[pAttrID][5], tQualityFactor[pQuality][1], tPartScale[pAttrID][vEquipType])
				-- 如果是武器，并且是计算攻击力，则需要以下进一步处理
			if (vEquipType == tItemType.mWeapon and ( pAttrID == 3 or pAttrID == 4 )) or
			   (vEquipType == tItemType.mSpirit and pAttrID == 1) then
				-- 攻击速度折算
				local vSpeed = nNormalAniSpeed / ( pAtkSpd / 100 )
				vBaseValue = vBaseValue * vSpeed / nNormalAtkSpeed

				-- 根据计算属性为攻击力下限或上限，计算相应的浮动
				local vWeaponAtkFloat = tWeaponAtkFloat[pType][1]
				local vAtkScale = tWeaponAtkFloat[pType][2]
				if pAttrID == 3 then
					vBaseValue = vBaseValue * ( 1 - vWeaponAtkFloat ) * vAtkScale
				elseif pAttrID == 4 then
					vBaseValue = vBaseValue * ( 1 + vWeaponAtkFloat ) * vAtkScale
				end
			end
			vAttrValueLow = vBaseValue * ( 1 - tExtendAttrFactor[pAttrID][6] )
			vAttrValueUp = vBaseValue * ( 1 + tExtendAttrFactor[pAttrID][6] )
		end
	end
--[[初始装备暂时废除	-- 判断是否初始装备并计算对应的初始装备系数
	local bPrimary = false
	for loop = 1, #tPrimaryEquip do
		if pID == tPrimaryEquip[loop] then
			bPrimary = true
			break
		end
	end
	if bPrimary then
		vAttrValueLow = vAttrValueLow * nPrimaryEquipFactor
		vAttrValueUp = vAttrValueUp * nPrimaryEquipFactor
	end		]]-- 初始装备暂时废除
	-- 最小取值 1，避免结果为0的情况
	vAttrValueLow = math.max(1, vAttrValueLow)
	vAttrValueUp = math.max(1, vAttrValueUp)
	-- print("			数值下限：" .. vAttrValueLow .. "	数值上限：" .. vAttrValueUp)
	return vAttrValueLow, vAttrValueUp
end

-- 获取装备附加属性数值
-- 传入参数：
-- 		pID = 装备的物品ID
-- 		pAttrLv = 装备属性等级
-- 		pQuality = 装备品质
-- 		pAttrID = 属性ID（扩展）
-- 返回值：
-- 		vAttrValueLow = 属性数值下限
-- 		vAttrValueUp = 属性数值上限
function GetEquipAffixAttrValue(pID, pType, pAttrLv, pQuality, pAttrID, pAtkSpd)
	local vAttrValueLow, vAttrValueUp = 0, 0
	local vEquipType = GetEquipType(pType, "WEAPON")
	-- print("		属性ID：" .. pAttrID .. "		内容：" .. tExtendAttrFactor[pAttrID][19])
	if pAttrID < 99 then
		-- 非技能属性数值
		if tExtendAttrFactor[pAttrID][2] == 0 then
		-- 百分比数值
			if pAttrID == 8 then
				-- MP的计算流程
				vAttrValueLow, vAttrValueUp = GetMPBase(pAttrLv, pQuality, 0)
				vAttrValueLow = vAttrValueLow * tExtendAttrFactor[pAttrID][17][1] * nRateMulti
				vAttrValueUp = vAttrValueUp * tExtendAttrFactor[pAttrID][17][2] * nRateMulti
			else
				-- 其他属性
				vAttrValueLow = tExtendAttrFactor[pAttrID][17][1] * nRateMulti
				vAttrValueUp = tExtendAttrFactor[pAttrID][17][2] * nRateMulti
				if pAttrID == 58 then
					-- 幸运值额外增加
					vAttrValueLow = vAttrValueLow + math.floor( ( pAttrLv - 1 ) / 10 )
					vAttrValueUp = vAttrValueUp + math.floor( ( pAttrLv - 1 ) / 5 )
				end
			end
		else
		-- 点数值
			if pAttrID == 7 then
				-- MP的计算流程
				vAttrValueLow, vAttrValueUp = GetMPBase(pAttrLv, pQuality, 1)
				vAttrValueLow = vAttrValueLow * tExtendAttrFactor[pAttrID][17][1]
				vAttrValueUp = vAttrValueUp * tExtendAttrFactor[pAttrID][17][2]
			else
				-- 其他属性
				local vWpnAtkScale = 1
				-- 武器附加攻击相关属性系数
				if vEquipType == tItemType.mWeapon and tExtendAttrFactor[pAttrID][17][3] == 1 then
					vWpnAtkScale = tWeaponAtkFloat[pType][3]
				end
				-- print("			计算基数：" .. tBaseAttrPoint[pAttrLv][tExtendAttrFactor[pAttrID][2]])
				vAttrValueLow = tBaseAttrPoint[pAttrLv][tExtendAttrFactor[pAttrID][2]] * tExtendAttrFactor[pAttrID][17][1] * vWpnAtkScale
				vAttrValueUp = tBaseAttrPoint[pAttrLv][tExtendAttrFactor[pAttrID][2]] * tExtendAttrFactor[pAttrID][17][2] * vWpnAtkScale
				print(tBaseAttrPoint[pAttrLv][tExtendAttrFactor[pAttrID][2]], tExtendAttrFactor[pAttrID][17][1], vWpnAtkScale);
				print(tBaseAttrPoint[pAttrLv][tExtendAttrFactor[pAttrID][2]], tExtendAttrFactor[pAttrID][17][2], vWpnAtkScale);
			end
		end
	else
		-- 技能属性数值
		if pAttrID == 99 then
			-- 全技能等级提升 - 有80%几率所有技能+1，有20%几率所有技能+2
			-- fix: 橙色100级以上，才会+2
			if pQuality >= 4 and pAttrLv >= 100 then
				vAttrValueLow = 2
			else
				vAttrValueLow = 1
			end
		else
			-- 单项技能 - 默认+1；30级以上，有67%几率+1，33%几率+2；45级以上，有50%几率+1，30%几率+2，20%几率+3
			local vRate = sw.randi(1, 100)
			if pAttrLv >=45 then
				if vRate <= 20 then
					vAttrValueLow = 3
				elseif vRate <= 50 then
					vAttrValueLow = 2
				else
					vAttrValueLow = 1
				end
			elseif pAttrLv >=30 then
				if vRate <= 33 then
					vAttrValueLow = 2
				else
					vAttrValueLow = 1
				end
			else
				vAttrValueLow = 1
			end
		end
		vAttrValueUp = vAttrValueLow
	end
--[[ 初始装备暂时废除	-- 判断是否初始装备并计算对应的初始装备系数
	local bPrimary = false
	for loop = 1, #tPrimaryEquip do
		if pID == tPrimaryEquip[loop] then
			bPrimary = true
			break
		end
	end
	if bPrimary then
		vAttrValueLow = vAttrValueLow * nPrimaryEquipFactor
		vAttrValueUp = vAttrValueUp * nPrimaryEquipFactor
	end		]] -- 初始装备暂时废除
	-- 最小取值 1，避免结果为0的情况
	vAttrValueLow = math.max(1, vAttrValueLow)
	vAttrValueUp = math.max(1, vAttrValueUp)

	-- print("			数值下限：" .. vAttrValueLow .. "	数值上限：" .. vAttrValueUp)
	return vAttrValueLow, vAttrValueUp
end

-- 获取镶嵌物属性
function GetGemAttr(pID, pAttrID)
	local vAttrValue1, vAttrValue2 = 0, 0
	-- 检测宝石ID在脚本列表中是否存在
	-- print("	—— 宝石数据 ——	宝石ID：" .. pID)
	local bExist = false
	if tGemAttrFactor[pID] then
		bExist = true
	end
	if bExist then
		local vGemGrade = tGemAttrFactor[pID][1]
		local vAttrID = pAttrID
		local vAttrLv = tGemAttrFactor[pID][2]
		local vQuality = 0
		if vGemGrade < 6 then
			vQuality = 3		-- 非传奇宝石以紫色品质为基准
		else
			vQuality = 5		-- 传奇宝石以暗金品质为基准
		end
		-- print("		第" .. vGemGrade .. "阶宝石；	属性ID：" .. vAttrID .. "；	属性内容：" .. tExtendAttrFactor[vAttrID][19] .. "；	属性等级：" .. vAttrLv)
		if tExtendAttrFactor[vAttrID][2] == 0 then
			if vAttrID == 8 then
				-- 法力值进行额外处理
				local vValueLow, vValueUp = GetMPBase(vAttrLv, vQuality, 0)
				vAttrValue1 = ( vValueLow + vValueUp ) / 2 * tExtendAttrFactor[vAttrID][18][vGemGrade] * nRateMulti
			else
				vAttrValue1 = tExtendAttrFactor[vAttrID][18][vGemGrade] * nRateMulti
			end
		else
			if vAttrID == 7 then
				-- 法力值进行额外处理
				local vValueLow, vValueUp = GetMPBase(vAttrLv, vQuality, 1)
				vAttrValue1 = ( vValueLow + vValueUp ) / 2 * tExtendAttrFactor[vAttrID][18][vGemGrade]
			else
				vAttrValue1 = GetGSBase(vAttrLv) * tExtendAttrFactor[vAttrID][5] * tExtendAttrFactor[vAttrID][18][vGemGrade]
			end
		end
		-- print("		属性 1 数值：" .. vAttrValue1 .. "	属性 2 数值：" .. vAttrValue2)
	else		-- 如果宝石ID不存在脚本设定中，则数值为-1（方便游戏中识别）
		-- print("	—— 未检测到对应宝石 " .. pID .. " 的数值设定")
		vAttrValue1, vAttrValue2 = -1, -1
	end
	return vAttrValue1, vAttrValue2
end

-- 系统接口 -------------------------------------------------
-- 计算装备的基础属性值
-- param[in] equ: 装备。属性：
--              id - 装备id
--              type - 类型
--              quality - 品质
--              attr_lv - 属性等级
--              attack_speed - 攻击速度，100表示默认速度（2秒1次），50表示一半的速度（4秒1次），200表示加快一倍（1秒1次）
-- param[in] attrType: 属性类型
-- return: 属性值
function CalEquipmentAttrib(equ, attrType)
	local vAttrValue = 0
	-- print("————基础属性计算————")
	-- print("	装备ID：" .. equ.id .. "	类型：" .. tItemType[equ.type] .. "	品质：" .. tQualityFactor[equ.quality][3])
	local vAttrValueLow, vAttrValueUp = GetEquipBaseAttrValue(equ.id, equ.type, equ.quality, equ.attr_lv, equ.attack_speed, attrType)
	-- 取 下限 至 上下限区间/3.5 之间的数值作为最终值
	local vDelta = math.max( 1, ( vAttrValueUp - vAttrValueLow ) / 3.5 )
	vAttrValue = sw.randi( vAttrValueLow, vAttrValueLow + vDelta )
	-- 点数属性按照品质，保证最小值不低于品质对应的值
	if tExtendAttrFactor[attrType][1][1] ~= 0 then
		vAttrValue = math.max( tQualityFactor[equ.quality][2], vAttrValue )
	end
	-- 最终值四舍五入取整
	vAttrValue = math.floor( vAttrValue + 0.5 )
	-- print("	基础属性值：" .. vAttrValue)
	return vAttrValue
end

-- 系统接口 -------------------------------------------------
-- 计算装备的附加属性值
-- param[in] equ: 装备。属性：
--              id - 装备id
--              type - 类型
--              quality - 品质
--              attr_lv - 属性等级
--              attack_speed - 攻击速度，100表示默认速度（2秒1次），50表示一半的速度（4秒1次），200表示加快一倍（1秒1次）
-- param[in] affixID: 附加属性效果id
-- return: 属性值1，属性值2。对应项不存在时返回nil
function CalEquipmentAffix(equ, affixID)
	local vAffixValue1, vAffixValue2 = 0, 0
	-- print("————附加属性计算————")
	-- print("	装备ID：" .. equ.id .. "	类型：" .. tItemType[equ.type] .. "	品质：" .. tQualityFactor[equ.quality][3])
	local vFloatLow, vFloatUp = GetEquipAffixAttrValue(equ.id, equ.type, equ.attr_lv, equ.quality, affixID, equ.attack_speed)
	print(vFloatLow, vFloatUp)
	if affixID < 99 then
		-- 非技能属性，根据品质取更偏向于最小值的随机值
			-- 取 下限 至 上下限区间/3.5 之间的数值作为最终值
		local vDelta = math.max( 1, ( vFloatLow - vFloatUp ) / 3.5 )
		vAffixValue1 = sw.randi( vFloatLow, vFloatLow + vDelta )
			-- 点数属性按照品质，保证最小值不低于品质对应的值
		if tExtendAttrFactor[affixID][1][1] ~= 0 then
			vAffixValue1 = math.max( tQualityFactor[equ.quality][2], vAffixValue1 )
		end
	else
		-- 技能属性使用原始值
		vAffixValue1 = vFloatLow
	end
	-- print("	附加属性值：" .. vAffixValue1)
	return vAffixValue1, vAffixValue2
end

