	elseif equID == 325002 and affixID == 468 then
		return 20, 15;
	elseif equID == 325003 and affixID == 503 then
		return 30, 0;
	elseif equID == 325004 and affixID == 203 then
		return 80, 40;
	elseif equID == 119018 and affixID == 287 then
		return 200, 0;
	elseif equID == 209018 and affixID == 401 then
		return 25, 0;
	end

	local t = tEquipSpecParam[affixID];
	if t then
		return sw.randi(t[1][1], t[1][2]), sw.randi(t[2][1], t[2][2])
	else
		return nil, nil
	end
end

