-- param[in] stage: 套装属性阶段
-- param[in] affixID: 套装属性效果id
-- return: 属性值1，属性值2。对应项不存在时返回nil
function CalEquipmentSuitAffix(equ, stage, affixID)
    return 1, 10;
end

-- 装备价格计算
-- 传入参数：
--		pLevel = 装备属性等级
--		pQuality = 装备品质
--		pType = 装备类型
--		pMode = 计算方式，字符串，"SELL"：出售价，"RECYCLE"：回收价
function GetEquipPrice(pLevel, pQuality, pType, pMode)
	local nPriceBaseFactor = 4.5		-- 装备价格基础系数
	local nPriceLvUpFactor = 0.09		-- 装备价格等级系数
	local vPriceValue = 0
	-- 获取装备类型
	local vEquipType = GetEquipType(pType, "WEAPON")
	-- 装备价格基数
	local vGoldBase = ( nPriceBaseFactor + nPriceLvUpFactor * ( pLevel - 1 ) ) * GetGSBase(pLevel) * tQualityFactor[pQuality][1] * tEquipTypePriceFactor[vEquipType][1]
	-- 装备的售价
		-- NPC出售价
	local vSellPrice = vGoldBase * tEquipTypePriceFactor[vEquipType][2]
		-- NPC回收价
	local vRecyclePrice = vGoldBase * tEquipTypePriceFactor[vEquipType][3]
	-- 判断返回值
	if pMode == "SELL" then
		vPriceValue = vSellPrice
	elseif pMode == "RECYCLE" then
		vPriceValue = vRecyclePrice
	end

	return vPriceValue
end

-- 系统接口 -------------------------------------------------
-- 计算装备售价
-- param[in] equ: 装备
function CalEquipmentSellGold(equ)
	local vEquipSellPrice = 0
	-- 计算回收价格基数。根据装备强化等级，每 1 级强化等级，售价提升 15%
	local vBasePrice = GetEquipPrice(equ.attr_lv, equ.quality, equ.type, "RECYCLE") * ( 1 + equ.inte_lv * 0.15 )
	if equ.attr_lv == 999 then
		-- 调试用装备售价固定为 1
		vBasePrice = 1
	end
--[[ 初始装备暂时废除	-- 判断是否初始装备并计算对应的初始装备系数
	for loop = 1, #tPrimaryEquip do
		if equ.id == tPrimaryEquip[loop] then
			vBasePrice = vBasePrice * nPrimaryEquipFactor
			break
		end
	end		]] -- 初始装备暂时废除
	-- 最终价格四舍五入取整
	vEquipSellPrice = math.floor( vBasePrice + 0.5 )

	return vEquipSellPrice
end

-- 系统接口 -------------------------------------------------
-- 计算装备强化数据
-- param[in] equ: 装备。属性：
--              id - 装备id
--              type - 类型
--              quality - 品质
--              inte_lv - 当前强化等级。0表示未强化过
--              attr_lv - 属性等级
--              attack_speed - 攻击速度，100表示默认速度（2秒1次），50表示一半的速度（4秒1次），200表示加快一倍（1秒1次）
--              base - 基础属性数组
--                  id - 附加属性效果id
--                  p1 - 附加属性参数1
--                  p2 - 附加属性参数2
-- return: table，包括
--              gold - 花费的金币（没有此项则表示不花费金币）
--              diamond - 花费的钻石（没有此项则表示不花费钻石）
--              success - 成功率，[0, 1]
--              base - 强化后的属性值数组。base[1]为第1个基础属性强化后的值
function CalEquipmentIntensify(equ)
	-- 返回值初始化
	local tEquipEnchance = {};
	tEquipEnchance.gold       = 0
	tEquipEnchance.diamond   = 0
	tEquipEnchance.success   = 0
	tEquipEnchance.base      = {}
	for loop = 1, #equ.base do
		tEquipEnchance.base[loop] = {}
		tEquipEnchance.base[loop].id = equ.base[loop].id
		tEquipEnchance.base[loop].p1 = equ.base[loop].p1
		tEquipEnchance.base[loop].p2 = equ.base[loop].p2
	end

	-- 强化等级未满才进行强化计算
	if equ.inte_lv < nEnchanceTimes then
		-- 计算强化价格
		local vPriceBase = GetEquipPrice(equ.attr_lv, equ.quality, equ.type, "SELL")
		local vPriceFactor = 1
--[[ 初始装备暂时废除		-- 判断是否初始装备并计算对应的初始装备系数
		for loop = 1, #tPrimaryEquip do
			if equ.id == tPrimaryEquip[loop] then
				vPriceFactor = nPrimaryEquipFactor
				break
			end
		end		]] -- 初始装备暂时废除
		tEquipEnchance.gold = math.floor( vPriceBase * tEnchanceCostFactor[equ.inte_lv+1][1] * vPriceFactor + 0.5 )
		-- 强化钻石花费，如果系数不为0，则最少为1
		if tEnchanceCostFactor[equ.inte_lv+1][2] > 0 then
            tEquipEnchance.gold = 0
			tEquipEnchance.diamond = math.max( 1, math.floor( vPriceBase * tEnchanceCostFactor[equ.inte_lv+1][2] * vPriceFactor + 0.5 ) )
		end
		-- 计算强化成功率
		local vRateBase = tEnchanceSuccessRate[equ.quality][equ.inte_lv+1][1]
		local vRateLvUp = tEnchanceSuccessRate[equ.quality][equ.inte_lv+1][2]
		local vRateGrade = tEnchanceSuccessRate[equ.quality][equ.inte_lv+1][3]
		if equ.attr_lv == 999 then
			-- 调试装备强化成功率固定为40%，金币消耗固定1000，钻石消耗固定200
			tEquipEnchance.success = 0.4
			tEquipEnchance.gold = 1000
		else
			tEquipEnchance.success = math.max( 0.01, vRateBase + vRateLvUp * math.floor( ( equ.attr_lv - 1 ) / vRateGrade ) )
		end
		-- 计算属性
		for loop = 1, #tEquipEnchance.base do
			local vBaseValue, vEnchanceInc = 0, 0
			if tExtendAttrFactor[equ.base[loop].id][2] == 0 then		-- 百分比属性
				vEnchanceInc = tExtendAttrFactor[equ.base[loop].id][equ.quality+11][1] / nEnchanceTimes + tExtendAttrFactor[equ.base[loop].id][equ.quality+11][2] * math.floor( ( equ.attr_lv - 1 ) / tExtendAttrFactor[tEquipEnchance.base[loop].id][4] )
				vBaseValue = equ.base[loop].p1 - math.floor( vEnchanceInc * equ.inte_lv * nRateMulti )
				tEquipEnchance.base[loop].p1 = vBaseValue + math.max( 1, vEnchanceInc * ( equ.inte_lv + 1 ) * nRateMulti )
			else		-- 点数属性
				vEnchanceInc = 1 + equ.inte_lv * nEnchanceImprove
				vBaseValue = math.floor( equ.base[loop].p1 / vEnchanceInc + 0.5 )
				tEquipEnchance.base[loop].p1 = vBaseValue + math.max( 1, vBaseValue * ( equ.inte_lv + 1 ) * nEnchanceImprove )
			end
		end
	end

    if (tEquipEnchance.gold > 10000) then
        tEquipEnchance.gold = math.floor(tEquipEnchance.gold / 100) * 100
    elseif (tEquipEnchance.gold > 10) then
        tEquipEnchance.gold = math.floor(tEquipEnchance.gold / 10) * 10
    end
    if (tEquipEnchance.diamond > 10) then
        tEquipEnchance.diamond = math.floor(tEquipEnchance.diamond / 10) * 10
    end
	return tEquipEnchance
end

-- 系统接口 -------------------------------------------------
-- 计算装备改造数据
-- param[in] equ: 装备
--              id - 装备id
--              type - 类型
--              quality - 品质
--              inte_lv - 当前强化等级。0表示未强化过
--              rem_count - 已改造过的次数
--              attr_lv - 属性等级
--              suit_id - 套装id
--              attack_speed - 攻击速度，100表示默认速度（2秒1次），50表示一半的速度（4秒1次），200表示加快一倍（1秒1次）
--              base - 基础属性数组
--                  id - 附加属性效果id
--                  p1 - 附加属性参数1
--                  p2 - 附加属性参数2
--              affix - 附加属性数组。每一项包括：
--                  id - 附加属性效果id
--                  p1 - 附加属性参数1
--                  p2 - 附加属性参数2
-- param[in] lockCount: 被锁定的属性个数
-- return: table，包括
--              gold - 花费的金币（没有此项则表示不花费金币）
--              diamond - 花费的钻石（没有此项则表示不花费钻石）
--              base - 数组。base[1]为第1个基础属性改造数值范围，由4个数组成的数组，依次为：p1最小值，p1最大值，p2最小值，p2最大值
--              affix - 数组。affix[1]为第1个附加属性改造数值范围，由4个数组成的数组，依次为：p1最小值，p1最大值，p2最小值，p2最大值
function CalEquipmentRemould(equ, lockCount)
	-- 返回值初始化
--	print("———— 改造计算调试 ————")
	local tEquipRemould = {}
	tEquipRemould.gold = 0
	tEquipRemould.diamond = 0
	tEquipRemould.base = {}
	for loop = 1, #equ.base do
		tEquipRemould.base[loop] = {}
		tEquipRemould.base[loop][1] = 0
		tEquipRemould.base[loop][2] = 0
		tEquipRemould.base[loop][3] = 0
		tEquipRemould.base[loop][4] = 0
	end
	tEquipRemould.affix= {}
	for loop = 1, #equ.affix do
		tEquipRemould.affix[loop] = {}
		tEquipRemould.affix[loop][1] = 0
		tEquipRemould.affix[loop][2] = 0
		tEquipRemould.affix[loop][3] = 0
		tEquipRemould.affix[loop][4] = 0
	end
--	print("	装备ID：" .. equ.id.. "	装备类型：" .. tItemType[equ.type] .. "	属性等级：" .. equ.attr_lv .. "	品质：" .. tQualityFactor[equ.quality][3])
	-- 计算改造费用
	local vGoldBase = GetEquipPrice(equ.attr_lv, equ.quality, equ.type, "SELL")
	local vPriceFactor = 1
--[[ 初始装备暂时废除	-- 判断是否初始装备并计算对应的初始装备系数
	for loop = 1, #tPrimaryEquip do
		if equ.id == tPrimaryEquip[loop] then
			vPriceFactor = nPrimaryEquipFactor
			break
		end
	end		]] -- 初始装备暂时废除
	if lockCount > 0 then		-- 有锁定才计算费用消耗
		if equ.attr_lv == 999 then
			-- 调试用装备费用固定为200 * 锁定条目数
			tEquipRemould.gold = 200 * lockCount
		else
			tEquipRemould.gold = vGoldBase * 0.2 * lockCount * vPriceFactor * tRemouldCostFactor[equ.inte_lv]
		end
--		if equ.inte_lv > 2 then
--			tEquipRemould.diamond = lockCount * GetEquipPrice(equ.attr_lv, equ.quality, equ.type, "SELL") * 0.025
--		end
	end
    -- 根据强化等级调整费用
    tEquipRemould.gold = tEquipRemould.gold * (0.5 + equ.inte_lv / 6);
    tEquipRemould.diamond = tEquipRemould.diamond * (0.5 + (equ.inte_lv - 3) / 3);

	local vMinValue, vMaxValue = 0, 0
	-- 基础属性改造
--	print("	基础属性改造——————————")
	for loop = 1, #equ.base do
		vMinValue, vMaxValue = GetEquipBaseAttrValue(equ.id, equ.type, equ.quality, equ.attr_lv, equ.attack_speed, equ.base[loop].id)
--		print("		属性" .. loop .. " -- ID：" .. equ.base[loop].id .. "		内容：" .. tExtendAttrFactor[equ.base[loop].id][19])
--		print("		原始数值：" .. tEquipRemould.base[loop][1] .. "		属性范围：" .. vMinValue .. " ~~ " .. vMaxValue)
		-- 改造上限根据属性数值类型（数值/百分比）以及强化等级进行进一步处理
		local vEnchanceInc = 0
		tEquipRemould.base[loop][1] = vMinValue
		if tExtendAttrFactor[equ.base[loop].id][2] == 0 then
			-- 百分比数值的强化增幅
			vEnchanceInc = tExtendAttrFactor[equ.base[loop].id][equ.quality+11][1] / nEnchanceTimes + tExtendAttrFactor[equ.base[loop].id][equ.quality+11][2] * math.floor( ( equ.attr_lv - 1 ) / tExtendAttrFactor[equ.base[loop].id][4] )
			-- 强化后属性上限提升
			local vMidValue = ( vMaxValue + vMinValue ) / 2
			local vDelta = ( vMaxValue - vMinValue ) / 2
			vMaxValue = math.floor( vMidValue + ( vEnchanceInc + tExtendAttrFactor[equ.base[loop].id][equ.quality+6][3] ) * equ.inte_lv * nRateMulti )
		else
			-- 强化后属性上限提升
			local vDelta = ( vMaxValue - vMinValue ) / 2
			vMaxValue = ( vMinValue + vDelta * ( 1 + equ.inte_lv / nEnchanceTimes ) ) * ( 1 + equ.inte_lv * nEnchanceImprove )
		end
		tEquipRemould.base[loop][2] = vMaxValue
--		print("		改造区间：" .. tEquipRemould.base[loop][1] .. " -- " .. tEquipRemould.base[loop][2])
	end
	-- 附加属性改造
--	print("	附加属性改造——————————")
	for loop = 1, #equ.affix do
		if equ.affix[loop].id < 99 then
			-- 非技能属性改造
			vMinValue, vMaxValue = GetEquipAffixAttrValue(equ.id, equ.type, equ.attr_lv, equ.quality, equ.affix[loop].id, equ.attack_speed)
			tEquipRemould.affix[loop][1] = vMinValue
			-- print("		属性" .. loop .. " -- ID：" .. equ.affix[loop].id .. "		内容：" .. tExtendAttrFactor[equ.affix[loop].id][19])
			-- print("		原始数值：" .. tEquipRemould.affix[loop][1] .. "		属性范围：" .. vMinValue .. " ~~ " .. vMaxValue)
			-- 改造上限随强化等级提升
			if tExtendAttrFactor[equ.affix[loop].id][2] == 0 then
				-- 百分比属性
				local vDelta = math.floor( vMaxValue / 8 ) + 1
				vMaxValue = ( vMaxValue + vMinValue ) / 2 + ( vMaxValue - vMinValue ) / 2 * equ.inte_lv + vDelta * equ.inte_lv
			else
				-- 点数属性
				local vDelta = ( vMaxValue - vMinValue ) / 2
				vMaxValue = vMinValue + vDelta * ( 1 + equ.inte_lv / nEnchanceTimes )
			end
			tEquipRemould.affix[loop][2] = vMaxValue
			-- print("		改造区间：" .. tEquipRemould.affix[loop][1] .. " -- " .. tEquipRemould.affix[loop][2])
		else
			-- 技能属性改造
			tEquipRemould.affix[loop][1] = equ.affix[loop].p1
			if equ.affix[loop].id == 99 then
				-- 全技能等级提升 - 最高 +2
				tEquipRemould.affix[loop][2] = 2
			else
				-- 单项技能 - 默认+1；30级以上，最高 +2；45级以上，最高 +3
				if equ.attr_lv >=45 then
					tEquipRemould.affix[loop][2] = 3
				elseif equ.attr_lv >=30 then
					tEquipRemould.affix[loop][2] = 2
				else
					tEquipRemould.affix[loop][2] = 1
				end
			end
		end
	end

    if (tEquipRemould.gold > 10000) then
        tEquipRemould.gold = math.floor(tEquipRemould.gold / 100) * 100
    elseif (tEquipRemould.gold > 10) then
        tEquipRemould.gold = math.floor(tEquipRemould.gold / 10) * 10
    end
    if (tEquipRemould.diamond > 10) then
        tEquipRemould.diamond = math.floor(tEquipRemould.diamond / 10) * 10
    end
	return tEquipRemould
end

-- 系统接口 -------------------------------------------------
-- 计算重铸附加属性池
-- return: [1] - 数组，5个元素，用于当前重铸装备的属性池。每一项元素同样为数组，内容为：属性id、p1、p2
--         [2] - 手动刷新属性池需要花费的钻石
function CalRecastPool(count, playerLv)
	-- print("———— 刷新重铸属性池 ————")
	local tRecastPool = {}
	-- 初始化筛选数组
	-- print("	生成属性池筛选表")
	local tFilter = {}
	local vAttrNumCount = 0
	local vTotalWeight = 0
		-- 筛选有效的属性条目，相关数据复制到筛选表
	for key, value in pairs(tExtendAttrFactor) do
		if tExtendAttrFactor[key][1][1] ~= 0 and tExtendAttrFactor[key][1][2] <= playerLv and key ~= 51 then
			vAttrNumCount = vAttrNumCount + 1
			tFilter[vAttrNumCount] = {}
			tFilter[vAttrNumCount].ID = key
			tFilter[vAttrNumCount].Weight = tExtendAttrFactor[key][1][1] ^ 2
			tFilter[vAttrNumCount].Level = tExtendAttrFactor[key][1][2]
			tFilter[vAttrNumCount].Rate = 0
			vTotalWeight = vTotalWeight + tFilter[vAttrNumCount].Weight
		end
	end
	-- print("	开始计算属性池数据……")
--[[	-- 计算权重平均值
	local vAverageWeight = vTotalWeight / #tFilter / 3
	-- 根据平均值调整，重新调整各项实际权重
	for loop1 = 1, #tFilter do
		tFilter[loop1].Weight = tFilter[loop1].Weight + vAverageWeight
	end ]] -- 权重的平均值加成暂时取消
	-- 生成重铸属性池
	for loop1 = 1, 5 do
		-- print("		第" .. loop1 .. "项")
		tRecastPool[loop1] = {}
		-- 计算权重和
		vTotalWeight = 0
		for loop2 = 1, #tFilter do
			vTotalWeight = vTotalWeight + tFilter[loop2].Weight
		end
		-- 根据权重比对筛选
		local vAttrRand = sw.randi(1, nDropRateUpLimit)
		-- print("			筛选几率取值：" .. vAttrRand)
		for loop2 = 1, #tFilter do
			-- 根据权重计算被筛选几率
			local vRate = math.floor( tFilter[loop2].Weight / vTotalWeight * nDropRateUpLimit + 0.5 )
			if loop2 == 1 then
				tFilter[loop2].Rate = vRate
			elseif loop2 == #tFilter then
				tFilter[loop2].Rate = nDropRateUpLimit
			else
				tFilter[loop2].Rate = tFilter[loop2-1].Rate + vRate
			end
			-- 判断属性是否被选中
			if vAttrRand <= tFilter[loop2].Rate then
				-- 记录被选中属性的参数
				tRecastPool[loop1].id = tFilter[loop2].ID
				tRecastPool[loop1].p1 = 1
				tRecastPool[loop1].p2 = 0
				-- 从筛选属性池中移除已经被选出的属性，避免筛选重复
				table.remove( tFilter, loop2 )
				-- print("				ID：" .. tFilter[loop2].ID .. " 筛选通过，内容：" .. tExtendAttrFactor[tFilter[loop2].ID][19])
				break
			end
		end
	end
	-- 计算刷新属性池所需花费（100钻起步，50钻步进，每3次一跳，1000钻上限）
	local nMinDiamond = 100
	local nUpLmt = 1000
	local nTimes = 2
	local nStep = 50
	local vDiamond = math.min( nUpLmt, nMinDiamond + nStep * math.floor( ( count - 1 ) / nTimes ) )
	-- print("	重铸花费：钻石 " .. vDiamond)
	return tRecastPool, vDiamond
end

-- 系统接口 -------------------------------------------------
-- 计算装备重铸花费
-- param[in] equ: 装备
-- param[in] affixSet: 重铸属性组
--              affixSet[1].id 表示第1条属性的id
--              affixSet[1].p 表示第1条属性的概率
-- param[in] index: 被重铸属性的索引，从1开始
-- param[in] count: 该属性已被重铸过的次数
-- return: table，包括
--              gold - 花费的金币（没有此项则表示不花费金币）
--              diamond - 花费的钻石（没有此项则表示不花费钻石）
function CalEquipmentRecast(equ, affixSet, index, count)
	-- 返回值初始化
	local tEquipRecast = {}
	tEquipRecast.gold = 0
	tEquipRecast.diamond = 0
	-- 重铸费用计算
		-- 游戏币费用
	local vGoldBase = GetEquipPrice(equ.attr_lv, equ.quality, equ.type, "SELL")
--  local vGoldFactor = GetGSBase(equ.inte_lv + 1) ^ 2 * 0.0018
	local vGoldFactor = 0.3
	local vPriceFactor = 1
--[[ 初始装备暂时废除	-- 判断是否初始装备并计算对应的初始装备系数
	for loop = 1, #tPrimaryEquip do
		if equ.id == tPrimaryEquip[loop] then
			vPriceFactor = nPrimaryEquipFactor
			break
		end
	end		]] -- 初始装备暂时废除
	if equ.attr_lv == 999 then
		-- 调试装备金币费用固定 10000
		tEquipRecast.gold = 10000
	else
		tEquipRecast.gold = math.max( 1, math.floor ( vGoldBase * vGoldFactor * vPriceFactor + 0.5 ) )
	end
		-- 钻石费用
	local nDiaCount = 0		-- 第 0 次免费
	if count >= nDiaCount then
        tEquipRecast.gold = 0
        tEquipRecast.diamond = math.min(1000, 50 + 50 * ( count - nDiaCount ))
	end

	return tEquipRecast
end

-- 系统接口 -------------------------------------------------
-- 计算道具的附加属性参数值（目前只有镶嵌宝石）
-- param[in] itemID: 道具id
-- param[in] itemType: 道具类型
-- param[in] quality: 道具品质
-- param[in] affixID: 附加属性id
-- return: [1] - p1, [2] - p2
function CalItemAffix(itemID, itemType, quality, affixID)
	local vAttrValue1, vAttrValue2 = 0, 0
--	print("———— 道具属性生成 ————")
	if itemType == tItemType.mGem then
		vAttrValue1, vAttrValue2 = GetGemAttr(itemID, affixID)
	elseif  itemType == tItemType.mPotion then
		local t = tPotionAffixValue[itemID]
		if (t) then
			vAttrValue1 = t[affixID] or 0;
		end
	end

	return vAttrValue1, vAttrValue2
end

-- 系统接口 -------------------------------------------------
-- 计算装备镶嵌花费
-- param[in] equ: 装备
-- param[in] oldGems: 数组，每一项为已镶嵌宝石的道具id，如果为nil，表示该位置未镶嵌宝石
-- param[in] newGems: 数组，每一项为准备镶嵌宝石的道具id，如果为nil，表示该位置不镶嵌新的宝石
-- return: table，包括
--              gold - 花费的金币（没有此项则表示不花费金币）
--              diamond - 花费的钻石（没有此项则表示不花费钻石）
function CalEquipmentInlay(equ, oldGems, newGems)
	local tInlayCost = { gold = 0, diamond = 0 }
    local base = equ.attr_lv * 50
    for i, v in pairs(newGems) do
        if (oldGems[i]) then
            tInlayCost.gold = tInlayCost.gold + base * 5
        else
            tInlayCost.gold = tInlayCost.gold + base
        end
    end
	return tInlayCost
end

-- 系统接口 -------------------------------------------------
-- 计算装备的得分
-- param[in] equ: 装备
--              id - 装备id
--              type - 类型
--              quality - 品质
--              attr_lv - 属性等级
--              suit_id - 套装id
--              attack_speed - 攻击速度，100表示默认速度（2秒1次），50表示一半的速度（4秒1次），200表示加快一倍（1秒1次）
--              base_hp - 基础hp
--              base_mp - 基础mp
--              base_min_atk - 基础最小攻击
--              base_max_atk - 基础最大攻击
--              base_def - 基础防御
--              base_fire_res - 基础火抗
--              base_cold_res - 基础冰抗
--              base_light_res - 基础雷抗
--              base_poison_res - 基础毒抗
--              base - 基础属性数组
--                  id - 附加属性效果id
--                  p1 - 附加属性参数1
--                  p2 - 附加属性参数2
--              affix - 附加属性数组。每一项包括：
--                  id - 附加属性效果id
--                  p1 - 附加属性参数1
--                  p2 - 附加属性参数2
function CalEquipmentScore(equ)
	local nDPSFactor = 1.5 		-- 武器DPS计算系数
	local nBaseFactor = 2		-- 基础属性权重系数
	local nAffixFactor = 2	-- 附加属性权重系数
	local vEquipType = GetEquipType(equ.type, "WEAPON")

	local vWeaponDPS = 0
	local vEquipScore = 0
	local vAttrValue, vAttrFactor = 0, 0

	-- print("———————— 装备分数计算 ————————")
	-- print("	装备ID：" .. equ.id .. "		装备类型：" .. tItemType[equ.type] .. "		装备品质：" .. equ.quality .. "		装备等级：" .. equ.attr_lv)
	-- 装备分数计算
		-- 基础属性部分
	-- print("	———— 基础属性部分")
	if vEquipType == tItemType.mWeapon then
			-- 如果是武器，需要将攻击力折算为DPS再计算分数
		local vAtkPow = ( equ.base[1].p1 + equ.base[2].p1 ) / 2
		local vWeaponSpeed = nNormalAniSpeed / ( equ.attack_speed / 100 )
		local vSpeedMulti = vWeaponSpeed / nNormalAtkSpeed
		vWeaponDPS = vAtkPow / vSpeedMulti
		vAttrFactor = tEquipScoreFactor[equ.attr_lv][1]
		vEquipScore = vEquipScore + vWeaponDPS * vAttrFactor * nDPSFactor / tWeaponAtkFloat[equ.type][2] * nBaseFactor
		-- print("		属性ID：1" .. "		属性内容：武器DPS")
		-- print("			属性数值：" .. vWeaponDPS .. "		GS系数：" .. vAttrFactor .. "		属性分数：" .. vWeaponDPS * vAttrFactor * nDPSFactor * 10 .. "		总分数：" .. vEquipScore * 10)
	else
		for loop = 1, #equ.base do
			-- print("		属性ID：" .. equ.base[loop].id .. "		属性内容：" .. tExtendAttrFactor[equ.base[loop].id][19])
			vAttrValue = equ.base[loop].p1
			vAttrFactor = tEquipScoreFactor[equ.attr_lv][equ.base[loop].id]
			vEquipScore = vEquipScore + vAttrValue * vAttrFactor * nBaseFactor
			-- print("			属性数值：" .. vAttrValue .. "		GS系数：" .. vAttrFactor .. "		属性分数：" .. vAttrValue * vAttrFactor * 10 .. "		总分数：" .. vEquipScore * 10 )
		end
	end
		-- 附加属性部分
			-- 遍历附加属性进行计算
	-- print("	———— 附加属性部分")
	for loop = 1, #equ.affix do
		-- 属性ID超出计分范围的，不计算分数
		if equ.affix[loop].id <= #tEquipScoreFactor[equ.attr_lv] then
			-- print("		属性ID：" .. equ.affix[loop].id .. "		属性内容：" .. tExtendAttrFactor[equ.affix[loop].id][19])
			vAttrValue = equ.affix[loop].p1
			vAttrFactor = tEquipScoreFactor[equ.attr_lv][equ.affix[loop].id]
			vEquipScore = vEquipScore + vAttrValue * vAttrFactor * tExtendAttrFactor[equ.affix[loop].id][3] * nAffixFactor
			-- print("			属性数值：" .. vAttrValue .. "		GS系数：" .. vAttrFactor .. "		属性分数：" .. vAttrValue * vAttrFactor * nAffixFactor * tExtendAttrFactor[equ.affix[loop].id][3] * 10 .. "		总分数：" .. vEquipScore * 10)
		end
	end
	-- print("	———— 装备总分数：" .. vEquipScore * 10)

	return vEquipScore * 10
end

-- 计算掉落集合 -------------------------------------------------
-- param[in] dropSet: 掉落总集合，数组。
--              dropSet[1].id 表示第1条掉落的id
--              dropSet[1].p 表示第1条掉落的概率
-- param[in] luck: 玩家幸运最终值
-- return: 返回掉落id
function CalDropID(dropSet, luck)
	local IDResult = 0
	-- 玩家幸运值对掉率的加成百分比
	local vDropRateIns = luck / nRateMulti
	-- 获取掉落集合总数量
	local vDropSetCount = #dropSet
	-- 复制掉表，并进行相关数据的初始化
	local tDropFilter = {}
	local vTotalFactor = 0
	local bRedBlueBottleDrop = false
	local vRedBlueBottleSerial = 0
	for loop = 1, vDropSetCount do
		tDropFilter[loop] = {}
		tDropFilter[loop].Range = 0
		tDropFilter[loop].ID = dropSet[loop].id
		tDropFilter[loop].Factor = dropSet[loop].p
		tDropFilter[loop].Rate = 0
		vTotalFactor = vTotalFactor + tDropFilter[loop].Factor
		if tDropFilter[loop].ID == 1 then
			vRedBlueBottleSerial = loop
		end
	end
	-- 如果掉表中有红蓝瓶，则额外处理，避免幸运值过高之后红蓝瓶掉落被挤占，玩家无法正常获得红蓝瓶
	if vRedBlueBottleSerial > 0 then
		tDropFilter[vRedBlueBottleSerial].Rate = math.floor( tDropFilter[vRedBlueBottleSerial].Factor / vTotalFactor * nDropRateUpLimit )
		local vBottleRate = sw.randi(1, nDropRateUpLimit)
		if vBottleRate <= tDropFilter[vRedBlueBottleSerial].Rate then
			bRedBlueBottleDrop = true
			IDResult = tDropFilter[vRedBlueBottleSerial].ID
		end
			-- 掉落过滤表移除红蓝瓶
		table.remove(tDropFilter, vRedBlueBottleSerial)
			-- 重新赋值过滤表长度
		vDropSetCount = #tDropFilter
			-- 重置系数和
		vTotalFactor = 0
			-- 重新计算系数和
		for loop = 1, vDropSetCount do
			vTotalFactor = vTotalFactor + tDropFilter[loop].Factor
		end
	end
	-- 如果没有红蓝瓶掉落，则计算各掉落项对应的圆桌百分比
	if not bRedBlueBottleDrop then
		-- 计算幸运加成后实际掉率
		for loop = 1, vDropSetCount do
			tDropFilter[loop].Rate = math.floor( tDropFilter[loop].Factor / vTotalFactor * ( 1 + vDropRateIns ) * nDropRateUpLimit )
		end
		-- 计算各集合的掉落取值区间
		for loop = vDropSetCount, 1, -1 do
			if loop == vDropSetCount then
				tDropFilter[loop].Range = nDropRateUpLimit
			else
				tDropFilter[loop].Range = tDropFilter[loop+1].Range - tDropFilter[loop+1].Rate
			end
			if tDropFilter[loop].Range <= 1 then
				tDropFilter[loop].Range = 1
				break
			end
		end
		-- 计算最终掉落的集合ID
		local vRandRate = sw.randi(1, nDropRateUpLimit)
		for loop = 1, vDropSetCount do
			if vRandRate <= tDropFilter[loop].Range then
				IDResult = tDropFilter[loop].ID
				break
			end
		end
	end
    return IDResult
end

-- 任务类型
local TaskType = {
    GATHER          = 1,    -- 收集道具
    KILL            = 2,    -- 杀怪
    VISIT           = 3,    -- 探访祭坛
    OPEN_BOX        = 4,    -- 开宝箱（包括木桶瓦罐等）
    EQUIPMENT       = 5,    -- 获得指定品质以上的装备
    HUNT            = 6,    -- 击杀指定品质以上的怪
    INTENSIFY       = 7,    -- 强化
    TRANSMUTE       = 8,    -- 合成
    AVOID_TRAP      = 9,    -- 躲避陷阱
};
-- 游戏资产类型
local AssetType = {
    GOLD        = 1,    -- 金币
    DIAMOND     = 2,    -- 钻石
    EXP         = 3,    -- 经验
    ITEM        = 4,    -- 道具
};
-- 地图物件类型
local MapObjType = {
    NONE                = 0,    -- 无
    WOOD_BOX            = 1,    -- 木宝箱
    GOLD_BOX            = 2,    -- 金宝箱
    DIAMOND_BOX         = 3,    -- 钻石宝箱
    CROCK               = 4,    -- 瓦罐
    BARREL              = 5,    -- 木桶
    WEAPON_RACK         = 6,    -- 武器架
    ARMOR_RACK          = 7,    -- 防具架
    TRINKET_BOX         = 8,    -- 饰品盒
    RED_SPRING          = 9,    -- 红泉（恢复hp）
    BLUE_SPRING         = 10,   -- 蓝泉（恢复mp）
    YELLOW_SPRING       = 11,   -- 黄泉（恢复hp和mp）
    RED_ALTAR           = 12,   -- 红祭坛（获得红瓶）
    BLUE_ALTAR          = 13,   -- 蓝祭坛（获得蓝瓶）
    YELLOW_ALTAR        = 14,   -- 黄祭坛（获得红瓶和蓝瓶）
    RETURN_STELE        = 15,   -- 回城碑
    OPEN_MAP            = 16,   -- 地图全亮
    DIAMOND_RED_ALTAR   = 17,   -- 钻石红祭坛（补满红瓶）
    DIAMOND_BLUE_ALTAR  = 18,   -- 钻石蓝祭坛（补满蓝瓶）
    BOMB                = 19,   -- 清场
    PORTAL              = 20,   -- 传送门
    BLOCK               = 21,   -- 障碍
    BILLBOARD           = 22,   -- 告示牌
};

local tRewardType =
{
	{ { TaskType.GATHER, TaskType.HUNT, TaskType.INTENSIFY }, AssetType.EXP, AssetType.ITEM },		-- 物品收集 / 蓝金怪击杀 / 装备强化，奖励：经验 & 道具
	{ { TaskType.KILL, TaskType.OPEN_BOX, TaskType.EQUIPMENT }, AssetType.GOLD, AssetType.EXP },		-- 普通怪击杀 / 开宝箱 / 获得指定品质装备，奖励：金币 & 经验
	{ { TaskType.VISIT, TaskType.AVOID_TRAP, TaskType.TRANSMUTE }, AssetType.GOLD, AssetType.ITEM }		-- 祭坛访问 / 陷阱躲避 / 物品合成，奖励：金币 & 道具
}

-- 经验或者金钱奖励数值尾数取整
function RoundGoldExp( pNum )
	local vInt, vDecimals = GetNumLength( pNum )
	return math.floor( pNum / 10 ^ math.floor( vInt / 2) ) * 10 ^ math.floor( vInt / 2)
end

-- 系统接口 -------------------------------------------------
-- 计算任务奖励
-- param[in] task 任务，子项包括：
--              type - 任务类型。所有任务均有此项
--              lv - 等级。所有任务均有此项
--      根据不同任务类型，更多的子项内容包括：
--          收集道具：num - 要求数量
--          杀怪：num - 要求数量
--          探访祭坛：无
--          开宝箱：obj - 宝箱类型（MapObjType），num - 要求数量
--          获得指定品质以上的装备：qua - 品质（1 - 4，白蓝紫橙），num - 要求数量
--          击杀指定品质以上的怪：qua - 品质（2蓝怪 3金怪），num - 要求数量
--          强化：num - 要求次数
--          合成：num - 要求次数
--          躲避陷阱：num - 要求次数
function CalTaskRewards(task)
	local vDifficulty = 0
	local tReward = {}
	tReward[1] = { t = AssetType.GOLD, n = 100 }
	tReward[2] = { t = AssetType.EXP, n = 200 }
	local vExp, vGold, vItemID, vNum = 0, 0, 0, 0
	local nExpFactor = 1.5
	local nGoldFactor = 5

	local tGoods = { 400300, 400301, 400302, 400303, 400304, 400305, 400306, 400307, 400308, 400309 }		-- 卖钱用杂货
	local tExp = { 400320, 400321, 400322, 400323, 400324, 400325, 400326, 400327, 400328, 400329 }		-- 经验道具，使用后获得经验
	local tMagicMaterial = { 400110, 400111, 400112, 400113, 400114 }		-- 蓝色装备拆分材料
	local tRareMaterial = { 400120, 400121, 400122, 400123, 400124 }		-- 紫色装备拆分材料
	local tUniqueMaterial = { 400130, 400131, 400132, 400133, 400134 }		-- 橙色装备拆分材料
	local tRecipeCoin = { 400105 }		-- 通用配方兑换币
	local tGem1 = { 420000, 420001, 420002, 420003, 420004, 420005, 420006, 420007 }		-- 1 阶宝石
	local tGem2 = { 420010, 420011, 420012, 420013, 420014, 420015, 420016, 420017 }		-- 2 阶宝石
	local tEnchance1 = { 400100 }		-- 1 阶强化石
	local tEnchance2 = { 400101 }		-- 2 阶强化石

	if task.type == TaskType.GATHER then
		-- 道具收集任务，基础难度 1，数量每增加 7.5，难度 +1
		-- 奖励：1、经验，根据等级，难度 3 为基准，每增减 1 难度，经验增减 10%
		-- 		2、道具，随机 1~3 个紫色材料，难度 1 为基准，每增加 2 难度，数量 +1
		vDifficulty = math.floor( task.num / 7.5 ) + 1
		vExp = tTaskReward[task.lv][1] * ( 1 + ( vDifficulty - 3 ) * 0.1 ) * nExpFactor
		local vGrade = math.min( #tRareMaterial, math.floor( ( task.lv - 1 ) / 20 ) + 1 )
		vItemID = tRareMaterial[vGrade]
		vNum = sw.randi( 1, 3 ) + math.floor( ( vDifficulty - 1 ) / 2 )
		tReward[1] = { t = AssetType.EXP, n = RoundGoldExp( vExp ) }
		tReward[2] = { t = AssetType.ITEM, id = vItemID, n = vNum }
		-- print("———— 任务类型：道具收集 ————")
		-- print("	任务等级：" .. task.lv .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：1" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算经验基数：" .. tTaskReward[task.lv][1] .. "	任务奖励经验：" .. tReward[1].n )
		-- print("		奖励道具：" .. vGrade .. " 阶紫色材料，ID：" .. vItemID .. "	数量：" .. vNum )
	elseif task.type == TaskType.KILL then
		-- 普通怪物击杀任务，基础难度 1，数量每增加 8，难度 +1
		-- 奖励：1、金币，根据等级，难度 2 为基准，每增减 1 难度，金币增减 10%
		-- 		2、经验，根据等级，难度 3 为基准，每增减 1 难度，经验增减 15%
		vDifficulty = math.floor( task.num / 8 ) + 1
		vExp = tTaskReward[task.lv][1] * ( 1 + ( vDifficulty - 3 ) * 0.15 ) * nExpFactor
		vGold = tTaskReward[task.lv][2] * ( 1 + ( vDifficulty - 2 ) * 0.1 ) * nGoldFactor
		tReward[1] = { t = AssetType.EXP, n = RoundGoldExp( vExp ) }
		tReward[2] = { t = AssetType.GOLD, n = RoundGoldExp( vGold ) }
		-- print("———— 任务类型：普通怪物击杀 ————")
		-- print("	任务等级：" .. task.lv .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：1" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算经验基数：" .. tTaskReward[task.lv][1] .. "	任务奖励经验：" .. tReward[1].n )
		-- print("		计算金币基数：" .. tTaskReward[task.lv][2] .. "	任务奖励金币：" .. tReward[2].n )
	elseif task.type == TaskType.VISIT then
		-- 祭坛访问任务，基础难度 2
		-- 奖励：1、金币，根据等级，60%比例
		-- 		2、道具，根据等级，随机蓝色材料 2~4 个
		vDifficulty = 2
		vGold = tTaskReward[task.lv][2] * 0.6 * nGoldFactor
		local vGrade = math.min( #tMagicMaterial, math.floor( ( task.lv - 1 ) / 20 ) + 1 )
		vItemID = tMagicMaterial[vGrade]
		vNum = sw.randi( 2, 4 )
		tReward[1] = { t = AssetType.GOLD, n = RoundGoldExp( vGold ) }
		tReward[2] = { t = AssetType.ITEM, id = vItemID, n = vNum }
		-- print("———— 任务类型：祭坛访问 ————")
		-- print("	任务等级：" .. task.lv )
		-- print("	任务难度基准：2" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算金币基数：" .. tTaskReward[task.lv][2] .. "	任务奖励金币：" .. tReward[1].n )
		-- print("		奖励道具：" .. vGrade .. " 阶蓝色材料，ID：" .. vItemID .. "	数量：" .. vNum )
	elseif task.type == TaskType.OPEN_BOX then
		-- 开宝箱任务，基础难度 1，按照瓦罐、木箱、金箱、钻石箱，数量每增加 10/6/4/2，难度 +1；木桶，数量每增加 8 个，难度 +1；武器架、防具架、饰品盒，数量每增加 5 个，难度 +1
		-- 奖励：1、金币，根据等级，难度 3 为基准，每增减 1 难度，金币增减 15%
		-- 		2、经验，根据等级，难度 3 为基准，80%比例，每增减 1 难度，经验增减 20%
		local tBoxToDiff = { 6, 4, 2, 10, 8, 5, 5, 5 }
		vDifficulty = math.floor( task.num / tBoxToDiff[task.obj] ) + 1
		vExp = tTaskReward[task.lv][1] * 0.8 * ( 1 + ( vDifficulty - 3 ) * 0.2 ) * nExpFactor
		vGold = tTaskReward[task.lv][2] * ( 1 + ( vDifficulty - 3 ) * 0.15 ) * nGoldFactor
		tReward[1] = { t = AssetType.EXP, n = RoundGoldExp( vExp ) }
		tReward[2] = { t = AssetType.GOLD, n = RoundGoldExp( vGold ) }
		-- print("———— 任务类型：开宝箱 ————")
		-- print("	任务等级：" .. task.lv .. "	宝箱类型：" .. task.obj .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：1" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算经验基数：" .. tTaskReward[task.lv][1] .. "	任务奖励经验：" .. tReward[1].n )
		-- print("		计算金币基数：" .. tTaskReward[task.lv][2] .. "	任务奖励金币：" .. tReward[2].n )
	elseif task.type == TaskType.EQUIPMENT then
		-- 获取装备任务，基础难度为所需装备的品质（1/2/3/4 - 白蓝紫橙），按照所需品质，数量每增加 白8 蓝4 紫2 橙1，难度 +1
		-- 奖励：1、金币，根据等级，基础难度为基准，每增减 1 难度，金币增减 20%
		-- 		2、经验，根据等级，基础难度为基准，每增减 1 难度，经验增减 20%
		local tQuaToDiff = { 8, 4, 2, 1 }
		vDifficulty = task.qua + math.floor( task.num / tQuaToDiff[task.qua] )
		vExp = tTaskReward[task.lv][1] * ( 1 + ( vDifficulty - task.qua ) * 0.2 ) * nExpFactor
		vGold = tTaskReward[task.lv][2] * ( 1 + ( vDifficulty - task.qua ) * 0.2 ) * nGoldFactor
		tReward[1] = { t = AssetType.EXP, n = RoundGoldExp( vExp ) }
		tReward[2] = { t = AssetType.GOLD, n = RoundGoldExp( vGold ) }
		-- print("———— 任务类型：收集装备 ————")
		-- print("	任务等级：" .. task.lv .. "	装备品质：" .. task.qua .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：" .. task.qua .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算经验基数：" .. tTaskReward[task.lv][1] .. "	任务奖励经验：" .. tReward[1].n )
		-- print("		计算金币基数：" .. tTaskReward[task.lv][2] .. "	任务奖励金币：" .. tReward[2].n )
	elseif task.type == TaskType.HUNT then
		-- 蓝/金怪击杀任务，基础难度为怪物品质（蓝2 金3），数量每增加 蓝5 金2，难度 +1
		-- 奖励：1、经验，根据等级，怪物品质 为难度基准，每增减 1 难度，经验增减 蓝20% 金25%
		-- 		2、道具，随机 2 阶宝石 1~3 个，怪物品质 为难度基准，每增加 1 难度，数量 +2
		local tQuaToDiff = { 5, 2 }
		local tExpToDiff = { 0.2, 0.25 }
		vDifficulty = task.qua + math.floor( task.num / tQuaToDiff[task.qua-1] )
		vExp = tTaskReward[task.lv][1] * ( 1 + ( vDifficulty - task.qua ) * tExpToDiff[task.qua-1] ) * nExpFactor
		local vGrade = sw.randi( 1, #tGem2 )
		vItemID = tGem2[vGrade]
		vNum = sw.randi( 1, 3 ) + ( vDifficulty - task.qua ) * 2
		tReward[1] = { t = AssetType.EXP, n = RoundGoldExp( vExp ) }
        tReward[2] = { t = AssetType.DIAMOND, n = 20 }
		-- tReward[2] = { t = AssetType.ITEM, id = vItemID, n = vNum }
		-- print("———— 任务类型：精英怪击杀 ————")
		-- print("	任务等级：" .. task.lv .. "	怪物品质：" .. task.qua .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：" .. task.qua .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算经验基数：" .. tTaskReward[task.lv][1] .. "	任务奖励经验：" .. tReward[1].n )
		-- print("		奖励道具：2 阶宝石，ID：" .. vItemID .. "	数量：" .. vNum )
	elseif task.type == TaskType.INTENSIFY then
		-- 装备强化任务，基础难度 1，数量每增加 3，难度 +1
		-- 奖励：1、经验，根据等级，难度 3 为基准，每增减 1 难度，经验增减 5%
		-- 		2、道具，随机 1 阶强化石 2~4 个，难度 1 为基准，每增加 1 难度，数量 +1
		vDifficulty = math.floor( task.num / 3 ) + 1
		vExp = tTaskReward[task.lv][1] * ( 1 + ( vDifficulty - 3 ) * 0.05 ) * nExpFactor
		vItemID = tEnchance1[1]
		vNum = sw.randi( 2, 4 ) + ( vDifficulty - 1 )
		tReward[1] = { t = AssetType.EXP, n = RoundGoldExp( vExp ) }
		tReward[2] = { t = AssetType.ITEM, id = vItemID, n = vNum }
		-- print("———— 任务类型：装备强化 ————")
		-- print("	任务等级：" .. task.lv .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：1" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算经验基数：" .. tTaskReward[task.lv][1] .. "	任务奖励经验：" .. tReward[1].n )
		-- print("		奖励道具：1 阶强化石，ID：" .. vItemID .. "	数量：" .. vNum )
	elseif task.type == TaskType.TRANSMUTE then
		-- 装备合成任务，基础难度 1，数量每增加 2，难度 +1
		-- 奖励：1、金币，根据等级，40%比例
		-- 		2、道具，根据等级，难度 1 为基准，随机 2~4 个经验道具，难度每增加 1，数量 +2
		vDifficulty = math.floor( task.num / 2 ) + 1
		vGold = tTaskReward[task.lv][2] * 0.4 * nGoldFactor
		local vGrade = math.min( #tExp, math.floor( ( task.lv - 1 ) / 20 ) + 1 )
		vItemID = tExp[vGrade]
		vNum = sw.randi( 2, 4 ) + ( vDifficulty - 1 ) * 2
		tReward[1] = { t = AssetType.GOLD, n = RoundGoldExp( vGold ) }
		tReward[2] = { t = AssetType.ITEM, id = vItemID, n = vNum }
		-- print("———— 任务类型：装备合成 ————")
		-- print("	任务等级：" .. task.lv .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：1" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算金币基数：" .. tTaskReward[task.lv][2] .. "	任务奖励金币：" .. tReward[1].n )
		-- print("		奖励道具：经验书，ID：" .. vItemID .. "	数量：" .. vNum )
	elseif task.type == TaskType.AVOID_TRAP then
		-- 躲避陷阱任务，基础难度 1，数量每增加 15，难度 +1
		-- 奖励：1、金币，根据等级，难度 1 为基准，每增加 1 难度，金币增加 15%
		-- 		2、道具，橙色材料 1~2 个，难度 1 为基准，每增加 1 难度，数量 +1
		vDifficulty = math.floor( task.num / 15 ) + 1
		vGold = tTaskReward[task.lv][2] * ( 1 + ( vDifficulty - 1 ) * 0.15 ) * nGoldFactor
		local vGrade = math.min( #tUniqueMaterial, math.floor( ( task.lv - 1 ) / 20 ) + 1 )
		vItemID = tUniqueMaterial[vGrade]
		vNum = sw.randi( 1, 2 ) + ( vDifficulty - 1 ) * 1
		tReward[1] = { t = AssetType.GOLD, n = RoundGoldExp( vGold ) }
		tReward[2] = { t = AssetType.ITEM, id = vItemID, n = vNum }
		-- print("———— 任务类型：机关躲避 ————")
		-- print("	任务等级：" .. task.lv .. "	需求数量：" .. task.num )
		-- print("	任务难度基准：1" .. "	实际任务难度：" .. vDifficulty )
		-- print("		计算金币基数：" .. tTaskReward[task.lv][2] .. "	任务奖励金币：" .. tReward[1].n )
		-- print("		奖励道具：" .. vGrade .. " 阶橙色材料，ID：" .. vItemID .. "	数量：" .. vNum )
	end

	return tReward;
end

-- 系统接口 -------------------------------------------------
-- 计算商店商品单价
-- param[in] goodsID: 商品的id
-- param[in] itemID: 道具id
-- param[in] count: 购买数量
-- param[in] equ: 如果是装备，则为装备数据，否则为nil
-- return: [1] - 货币类型，AssetType.GOLD：金币；AssetType.DIAMOND：钻石
--         [2] - 货币数量
function CalShopGoodsPrice(goodsID, itemID, count, equ)
	local vGoldPrice = GetEquipPrice(equ.attr_lv, equ.quality, equ.type, "SELL")
	local vPriceFactor = 1
--[[ 初始装备暂时废除	-- 判断是否初始装备并计算对应的初始装备系数
	for loop = 1, #tPrimaryEquip do
		if equ.id == tPrimaryEquip[loop] then
			vPriceFactor = nPrimaryEquipFactor
			break
		end
	end		]] -- 初始装备暂时废除
	local vInt, vDec = GetNumLength( vGoldPrice * vPriceFactor )
	vGoldPrice = math.floor( vGoldPrice / 10 ^ math.floor( vInt / 2 ) + 0.5 ) * 10 ^ math.floor( vInt / 2 )
	return AssetType.GOLD, vGoldPrice
end

-- 系统接口
-- 玩家初始化数据
function InitNewPlayer()
	local tNewPlayer = {}
	tNewPlayer.gold = 0
	tNewPlayer.diamond = 0
	tNewPlayer.red_bottle = 10
	tNewPlayer.blue_bottle = 10
	tNewPlayer.equip_ids = { 110000 }

	return tNewPlayer
end

-- 系统接口 -------------------------------------------------
-- 随机地图配置
-- param[in] floor: 层数
-- param[in] level: 地图等级
-- return: 配置参数
--          deep - 地图深度，用于确定可通行格数（两者数量大致相当），范围[100, 900]
--          monster - 怪物数量
--          blue_monster - 蓝怪
--          gold_monster - 金怪
--          diamond_box - 钻石宝箱数
--          gold_box - 金宝箱数
--          wood_box - 木宝箱数
--          weapon_rack - 武器架数
--          armor_rack - 防具架数
--          trinket_box - 饰品盒数
--          crock - 瓦罐数
--          barrel - 木桶数
--          altar - 祭坛数量
function GetMapConfig(floor, level)
	-- 返回值初始化
	local tMapSetting = {}
	tMapSetting.deep = 60
	tMapSetting.monster = 5
	tMapSetting.blue_monster = 0
	tMapSetting.gold_monster = 0
	tMapSetting.wood_box = 0
	tMapSetting.gold_box = 0
	tMapSetting.diamond_box = 0
	tMapSetting.armor_rack = 0
	tMapSetting.trinket_box = 0
	tMapSetting.weapon_rack = 0
	tMapSetting.crock = 0
	tMapSetting.barrel = 0
	tMapSetting.altar = 0
	-- 计算本层可行走面积
		-- MIN(最大尺寸, 起始值 + 层数 * 层数系数 + 层数-1 对层数段取余 * 层数调整系数) * (1 ± 浮动范围)
	local vBlockBase = math.min( 500, 100 + floor * 3 + (( floor - 1 ) % 10) * 6 )
	local vDeepBase = sw.randi( vBlockBase * 0.8, vBlockBase * 1.2 )
	tMapSetting.deep = math.floor( vDeepBase )
	-- 计算敌人数量
		-- 单层基数：随机（地图深度 / 最小系数，地图深度 / 最大系数） * （1 + 等级 / 等级系数）
	local vEnemyCount = math.floor( sw.randi( vDeepBase / 9, vDeepBase / 8 ) * ( 1 + level / 300 ) )
		-- 蓝色怪物：大于8级，随机（0，基数 / 蓝怪比例）；大于5级，小于等于8级，随机（0，1）
	if floor > 5 then
		if floor > 8 then
			tMapSetting.blue_monster = math.floor( sw.randi( 0, vEnemyCount / 4 ) )
		else
			tMapSetting.blue_monster = sw.randi( 0, 1 )
		end
	end
		-- 金色怪物：大于10级，MIN（2，随机（0，基数 / 金怪比例））；大于7级，小于等于10级，随机（0，1）
	if level > 7 then
		if level > 10 then
			tMapSetting.gold_monster = math.min( 2, math.floor( sw.randi( 0, vEnemyCount / 12 ) ) )
		else
			tMapSetting.gold_monster = sw.randi( 0, 1 )
		end
	end
		-- 普通怪物：基数 - 蓝怪数量 - 金怪数量
	tMapSetting.monster = math.max( 0, vEnemyCount - tMapSetting.blue_monster - tMapSetting.gold_monster )
	-- 计算箱子数量
		-- 计算普通箱子数量（25%几率1个，40%几率2个，30%几率3个，5%几率4个），地图面积有加成，总数量不超过地图等级
	local tWoodBoxRate = { 25, 65, 95, 100 }
	local vWoodBoxRate = sw.randi( 1, 100 )
	for loop = 1, #tWoodBoxRate do
		if vWoodBoxRate <= tWoodBoxRate[loop] then
			tMapSetting.wood_box = math.min( level, loop + math.floor( sw.randi( math.max( 0, ( vDeepBase - 100 ) / 120 ), math.max( 0, ( vDeepBase - 100 ) / 80 ) ) ) )
			break
		end
	end
		-- 大于5级，60%概率出现金箱子，地图面积有加成，最多不超过3个
	if floor > 5 and sw.randi( 1, 10000 ) <= 6000 then
		tMapSetting.gold_box = math.min( 3, 1 + sw.randi( 0, math.floor( sw.randi( math.max( 0, ( vDeepBase - 100 ) / 200 ), math.max( 0, ( vDeepBase - 100 ) / 150 ) ) ) ) )
	end
		-- 大于7级，15%概率出现钻石箱子
	if level > 7 then
		if sw.randi( 1, 10000 ) <= 1500 then
			tMapSetting.diamond_box = 1
		end
	end
	-- 计算武器架、防具架、饰品架数量
	local vShelfCount = sw.randi( 1, 3 ) - 1
	local tShelfCount = { 0, 0, 0 }
	if vShelfCount > 0 then
		local tShelfRate = { { 625, "Armor" }, { 875, "Jewelry" }, { 1000, "Weapon" } }
		for loop1 = 1, vShelfCount do
			local vRate = sw.randi( 1, 1000 )
			for loop2 = 1, #tShelfRate do
				if vRate <= tShelfRate[loop2][1] then
					tShelfCount[loop2] = tShelfCount[loop2] + 1
					break
				end
			end
		end
	end
	tMapSetting.armor_rack = tShelfCount[1]
	if level > 5 then
		-- 大于 5 级才会出现首饰盒
		tMapSetting.trinket_box = tShelfCount[2]
	end
	tMapSetting.weapon_rack = tShelfCount[3]
	-- 计算瓦罐、木桶、祭坛数量
	tMapSetting.crock = sw.randi( 1, 3 ) - 1
	tMapSetting.barrel = sw.randi( 1, 3 ) - 1
	tMapSetting.altar = sw.randi( 1, 3 ) - 1

	return tMapSetting
end

-- 系统接口 -------------------------------------------------
-- 解锁包裹页的花费
-- param[in] page: 当前已拥有的页数
-- return: [1] - 花费的类型，[2] - 花费的数量
function CalUnlockPackageCost(page)
    local tUnlockBagAsset, tUnlockBagDiamond;
    if INLAND_VERSION then
        tUnlockBagAsset = { AssetType.GOLD, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND }
        tUnlockBagDiamond = { 10000, 300, 1000, 2500, 4000, 6000, 6000, 6000 }
    else
        tUnlockBagAsset = { AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND, AssetType.DIAMOND }
        tUnlockBagDiamond = { 50, 450, 1000, 2500, 6000, 6000, 6000, 6000 }
    end
    local vNextPage = math.min(#tUnlockBagDiamond, page)
	return tUnlockBagAsset[vNextPage], tUnlockBagDiamond[vNextPage]
end

-- 材料ID对应材料分类集合检测
-- 传入参数：
-- 		tStuff = 所使用的材料ID序列（共3项）
-- 返回值：
-- 		tStuffGroup = 材料所属集合序列，包含：
--			ID = 材料的物品ID
-- 			Group = 材料所属物品集合的序号
-- 			Index = 材料在该集合中的排位序号
function StuffToGroup( tStuff )
	local tStuffGroup = {}
	local vErrCode = 0
	local vStuffMatch = 0
	-- 计算材料所属物品分类的序号以及在该序号集合内的位置
	for loop1 = 1, #tStuff do
		local bMatch = false
		for loop2 = 1, #tMaterialGroup do
			for loop3 = 1, #tMaterialGroup[loop2][1] do
				if tStuff[loop1] == tMaterialGroup[loop2][1][loop3] then
					vStuffMatch = vStuffMatch + 1
					tStuffGroup[vStuffMatch] = {}
					tStuffGroup[vStuffMatch].ID = tStuff[loop1]
					tStuffGroup[vStuffMatch].Group = loop2
					tStuffGroup[vStuffMatch].Index = loop3
					bMatch = true
					break
				end
			end
			if bMatch then
				break
			end
		end
	end
	if vStuffMatch < 3 then
		vErrCode = 241		-- 放入了无效的材料
		-- print("	—— 材料检测：")
		-- print("		放入了无效的材料")
	-- else
		-- print("	—— 材料检测：")
		-- for loop = 1, #tStuffGroup do
			-- print("		材料" .. loop .. "：	ID：" .. tStuffGroup[loop].ID .. "	所属集合：" .. tStuffGroup[loop].Group .. " = " ..  tMaterialGroup[tStuffGroup[loop].Group][3] .. "	集合内序号：" .. tStuffGroup[loop].Index)
		-- end
	end
	return tStuffGroup, vErrCode
end

-- 检测材料ID符合的配方序号
-- 传入参数：
-- 		tStuff = 所使用的材料序列（共3项）
-- 返回值：
-- 		vResultID = 符合需求的配方ID（详见 tRecipeDefine ）
function RecipeMatchCheck( tStuff )
	local vMatchCount1, vMatchCount2, vMatchCount3 = 0, 0, 0
	local vRecipeID, vErrCode = 0, 0

	if #tStuff >= 3 then		-- 所有材料都能够在物品分类中匹配到位置，则进行配方检测
		-- 设定配方计算用过滤表，并初始化
		local tRecipeFilter = {}
		for loop1 = 1, #tRecipeConfig do
			tRecipeFilter[loop1] = {}
			for loop2 = 1, 3 do
				tRecipeFilter[loop1][loop2] = {}
				for loop3 = 1, #tRecipeConfig[loop1][loop2] do
					tRecipeFilter[loop1][loop2][loop3] = tRecipeConfig[loop1][loop2][loop3]
				end
			end
		end
		-- 检测材料1符合的配方序列
		for loop1 = 1, #tRecipeFilter do		-- 配方总表循环
			local bStuff = false
			for loop2 = 1, #tRecipeFilter[loop1] do		-- 单个配方的材料集合循环
				for loop3 = 1, #tRecipeFilter[loop1][loop2] do		-- 材料集合内的ID循环
					if tStuff[1].Group == tRecipeFilter[loop1][loop2][loop3] then
						-- 检测到符合的材料，删除材料对应的集合，设置检测标识，用于跳出至下一个配方
						vMatchCount1 = vMatchCount1 + 1
						table.remove( tRecipeFilter[loop1], loop2 )
						bStuff = true
						break
					end
				end
				if bStuff then
					break
				end
			end
		end
		-- 在材料1检测结果的基础上，检测材料2符合的配方序列
		if vMatchCount1 > 0 then
			for loop1 = 1, #tRecipeFilter do		-- 配方总表循环
				local bStuff = false
				for loop2 = 1, #tRecipeFilter[loop1] do		-- 单个配方的材料集合循环
					for loop3 = 1, #tRecipeFilter[loop1][loop2] do		-- 材料集合内的ID循环
						if tStuff[2].Group == tRecipeFilter[loop1][loop2][loop3] then
							-- 检测到符合的材料，删除材料对应的集合，设置检测标识，用于跳出至下一个配方
							vMatchCount2 = vMatchCount2 + 1
							table.remove( tRecipeFilter[loop1], loop2 )
							bStuff = true
							break
						end
					end
					if bStuff then
						break
					end
				end
			end
		end
		-- 在材料1和材料2检测结果的基础上，检测材料3符合的配方序列
		if vMatchCount1 > 0 and vMatchCount2 > 0 then
			for loop1 = 1, #tRecipeFilter do		-- 配方总表循环
				local bStuff = false
				for loop2 = 1, #tRecipeFilter[loop1] do		-- 单个配方的材料集合循环
					for loop3 = 1, #tRecipeFilter[loop1][loop2] do		-- 材料集合内的ID循环
						if tStuff[3].Group == tRecipeFilter[loop1][loop2][loop3] then
							-- 检测到符合的材料，删除材料对应的集合，设置检测标识，用于跳出至下一个配方
							vMatchCount3 = vMatchCount3 + 1
							table.remove( tRecipeFilter[loop1], loop2 )
							bStuff = true
							break
						end
					end
					if bStuff then
						break
					end
				end
			end
		end
		-- 选出同时符合3种材料的配方
		if vMatchCount1 > 0 and vMatchCount2 > 0 and vMatchCount3 > 0 then
			for loop = 1, #tRecipeFilter do
				if #tRecipeFilter[loop] == 0 then
					vRecipeID = loop
					break
				end
			end
		end
	end
	if vRecipeID == 0 then
		vErrCode = 242		-- 当前材料组合没有适合的配方
		-- print("	—— 配方检测 。 。 。无匹配的配方")
	-- else
		-- print("	—— 配方检测 。 。 。匹配成功：" .. tRecipeDefine[vRecipeID])
	end

	return vRecipeID, vErrCode
end

-- 计算合成结果的ID集合
function GetProduct( pRecipeID )
	local vProductID = 0
	local tProduct = {}
	local vTotalFactor = 0
	for loop = 4, #tRecipeConfig[pRecipeID] - 1 do
		vTotalFactor = vTotalFactor + tRecipeConfig[pRecipeID][loop][2]
		tProduct[loop-3] = {}
		tProduct[loop-3].ID = tRecipeConfig[pRecipeID][loop][1]
		tProduct[loop-3].Factor = tRecipeConfig[pRecipeID][loop][2]
		tProduct[loop-3].Rate = 0
		tProduct[loop-3].Low = 0
		tProduct[loop-3].Up = 0
	end
	if #tProduct > 1 then
		local vProductRate = sw.randi( 1, nDropRateUpLimit )
		for loop = 1, #tProduct do
			tProduct[loop].Rate = math.floor( tProduct[loop].Factor / vTotalFactor * nDropRateUpLimit )
			if loop == 1 then
				tProduct[loop].Low = 1
			else
				tProduct[loop].Low = tProduct[loop-1].Up + 1
			end
			if loop == #tProduct then
				tProduct[loop].Up = nDropRateUpLimit
			else
				tProduct[loop].Up = tProduct[loop].Low + tProduct[loop].Rate - 1
			end
			if vProductRate >= tProduct[loop].Low and vProductRate <= tProduct[loop].Up then
				vProductID = tProduct[loop].ID
				break
			end
		end
	else
		vProductID = tProduct[1].ID
	end

	return vProductID
end

-- 系统接口 -------------------------------------------------
-- 合成
-- param[in] items: 作为材料的道具数组，每一项包括（需要道具的等级，堆叠性道具还需要只能单次合成所需的数量）
--              id: 道具id
--              type: 道具类型
--              quality: 品质
--              attr_lv: 属性等级
-- return: 两个值
--              [1]：错误码（对应string表索引），0 表示成功
--              [2]：结果道具id，失败返回 0
function CalTransmute(items)
	local vErrCode, vProductID = 0, 0
	local tStuff = { items[1].id, items[2].id, items[3].id }
	local vProductGroup, vProductIndex = 0, 0
	local vRecipeID = 0
	local tStuffGroup = {}
	-- print("———— 合成计算开始 ————")
	-- print("	材料ID：", items[1].id, items[2].id, items[3].id)
	-- 原料和配方对应检测
	tStuffGroup, vErrCode = StuffToGroup( tStuff )
	if vErrCode == 0 then
		vRecipeID, vErrCode = RecipeMatchCheck( tStuffGroup )
		if vErrCode == 0 then
			local vProduct = GetProduct( vRecipeID )
			if vRecipeID >= tRecipeDefine.Gem1Upgrade and vRecipeID <= tRecipeDefine.Gem4Upgrade then
			-- 宝石进阶（3 同色同级宝石 = 1 同色的高一级宝石，3 异色同级宝石 = 1 随机的高一级宝石）
				-- 计算成品的物品集合序号
				vProductGroup = vProduct
				if tStuffGroup[1].Index == tStuffGroup[2].Index and tStuffGroup[2].Index == tStuffGroup[3].Index then		-- 同色宝石则颜色保留，否则颜色随机
					vProductIndex = tStuffGroup[1].Index
				else
					vProductIndex = sw.randi( 1, #tMaterialGroup[vProductGroup][1] )
				end
			elseif vRecipeID >= tRecipeDefine.NormalWeapon and vRecipeID <= tRecipeDefine.NewRareEquip then
			-- 普通装备合成（3 普通装备（不同类型） = 1 随机的同品质装备 or 1 碎裂的强化石 or 1 白装杂物，3 普通装备（相同类型） = 1 随机的同类型同品质装备 or 1 碎裂的强化石 or 1 白装杂物）
			-- 魔法装备合成（3 魔法装备（任意类型） = 1 随机的同品质装备 or 1 裂开的强化石 or 1 蓝装杂物，3 魔法装备（相同类型） = 1 随机的同类型同品质装备 or 1 裂开的强化石 or 1 蓝装杂物）
			-- 稀有装备合成（3 稀有装备（任意类型） = 1 随机的同品质装备 or 1 方正的强化石 or 1 紫装杂物，3 稀有装备（相同类型） = 1 随机的同类型同品质装备 or 1 方正的强化石 or 1 紫装杂物）
			-- 传奇装备合成（3 传奇装备（任意类型） = 1 随机的同品质装备 or 1 无瑕的强化石 or 1 暗金杂物，3 传奇装备（相同类型） = 1 随机的同类型同品质装备 or 1 无瑕的强化石 or 1 暗金杂物）
			-- 1 级装备与其他任何装备合成，均为 1 级装备或者对应品质杂物，无法合成出强化石
				-- 计算成品的物品集合序号
				if tMaterialGroup[vProduct][2] >= 10 and tMaterialGroup[vProduct][2] <= 31 then		-- 如果合成结果是非新手装备
					if tStuffGroup[1].Group == tStuffGroup[2].Group and tStuffGroup[2].Group == tStuffGroup[3].Group then		-- 如果是同类型装备，则成品为同类型装备
						vProductGroup = tStuffGroup[1].Group
					else		-- 非同类装备，则按照计算结果决定类型
						vProductGroup = vProduct
					end
					vProductIndex = math.floor( ( tStuffGroup[1].Index + tStuffGroup[2].Index + tStuffGroup[3].Index ) / 3 )		-- 计算成品装备的平均等级
				elseif tMaterialGroup[vProduct][2] == 90 then		-- 如果合成结果是新手装备
					vProductGroup = vProduct
					vProductIndex = sw.randi( 1, #tMaterialGroup[vProductGroup][1] )
				else 		-- 其他非装备类结果
					vProductGroup = vProduct
					if tMaterialGroup[vProductGroup][2] == 43 then		-- 强化石
						vProductIndex = sw.randi( 1, #tMaterialGroup[vProductGroup][1] )
					else		-- 杂物
						vProductIndex = math.min( #tMaterialGroup[vProductGroup][1], math.floor( ( tStuffGroup[1].Index + tStuffGroup[2].Index + tStuffGroup[3].Index ) / 3 / 2 + 0.5 ) )	-- 计算杂物的平均等级
					end
				end
			elseif vRecipeID >= tRecipeDefine.RareLightWeaponToUnique and vRecipeID <= tRecipeDefine.RareRingToUnique then
			-- 稀有装备升传奇（1 稀有装备（任意类型） + 1 完美宝石（任意类型） + 1 神圣宝珠 = 1 同类型的传奇装备）
				-- 计算成品的物品集合序号
				vProductGroup = vProduct
				local vIndex = math.floor( ( tStuffGroup[1].Index + tStuffGroup[2].Index + tStuffGroup[3].Index ) / 3 )		-- 计算成品装备的平均等级
				vProductIndex = sw.randi( 1, vIndex )
			else
			-- 神圣宝珠碎片合成（3 同类型武器（普通、魔法、稀有各一） = 1 神圣宝珠碎片）
			-- 崇高宝珠碎片合成（3 同类型防具（普通、魔法、稀有各一） = 1 崇高宝珠碎片）
			-- 神圣宝珠合成（3 神圣宝珠碎片 = 1 神圣宝珠）
			-- 崇高宝珠合成（3 崇高宝珠碎片 = 1 崇高宝珠）
			-- 强化石进阶
			-- 成品ID唯一，无需计算
				-- 计算成品的物品集合序号
				vProductGroup = vProduct
				vProductIndex = sw.randi( 1, #tMaterialGroup[vProductGroup][1] )
			end
		end
	end

	if vErrCode == 0 then
	-- 成功则计算最终产物ID
		vProductID = tMaterialGroup[vProductGroup][1][vProductIndex]
		-- print("———— 本次合成计算完毕 ————	最终产物：" .. tMaterialGroup[vProductGroup][3] .. "	ID：" .. vProductID)
	else
	-- 不成功则返回0
		vProductID = 0
		-- print("———— 本次合成计算完毕 ————	合成失败，错误码：" .. vErrCode)
	end

	return vErrCode, vProductID
end

