-- 分解获得材料的公式
-- param[in] equ: 待分解的装备
-- return: [1] - 材料id，[2] - 材料数量
function CalBreakupMaterial(equ)
	local vAttrLv = equ.attr_lv
	local vQuality = equ.quality
	local vEnchanceLv = equ.inte_lv

	if equ.type == tItemType.mSpirit then
		local vMaterialsID = 400190
		local baseNum = 0

		if vQuality <= 2 then
			baseNum = 40
		elseif vQuality == 3 then
			baseNum = 160
		elseif vQuality == 4 then
			baseNum = 480
		else
			baseNum = 2400
		end
		return vMaterialsID, baseNum
	elseif equ.is_fashion then
		local vMaterialsID = 400196
		local baseNum = 0

		if vQuality <= 1 then
			baseNum = 1
		elseif vQuality == 2 then
			baseNum = 5
		elseif vQuality == 3 then
			baseNum = 20
		else
			if equ.type == tItemType.mLight or equ.type == tItemType.mHeavy or equ.type == tItemType.mPolearms then
				baseNum = 360
			else
				baseNum = 180
			end
		end
		return vMaterialsID, baseNum
	else
		local vMaterialsGroup = math.min( #tItemGroup, vQuality - 1 )
		local vMaterialsIndex = math.min( #tItemGroup[vMaterialsGroup][1], math.floor( ( vAttrLv - 1 ) / 20 ) + 1 )
		local vMaterialsNum = math.floor( ( ( vAttrLv - 1 ) % 20 ) / 6 ) + 1 + math.floor( equ.inte_lv - 1 / 3 ) + 1

		local vMaterialsID = tItemGroup[vMaterialsGroup][1][vMaterialsIndex]
		return vMaterialsID, vMaterialsNum
	end
end

-- 宠物吃一个道具获得的经验
-- param[in] item: 装备或道具
-- return: 经验值
function CalPetExpFromItem(item)
    if (item.type > 0 and item.type <= tItemType.mRing) then
        if (item.quality == 1) then
            return 100
        elseif (item.quality == 2) then
            return 300
        elseif (item.quality == 3) then
            return 1000
        elseif (item.quality == 4) then
            return 4000
        end
    end
    return 0
end


	
